import re
import math
from datetime import datetime

DATA_PATH = "/app/dataset/data.csv"


def parse_amount(raw):
    s = raw.strip()
    if s == "":
        return float("nan")

    negative = False
    if "CR" in s.upper():
        negative = True
    if "(" in s or ")" in s:
        negative = True
    if "-" in s:
        negative = True

    s2 = s.replace("C1", "").replace("C2", "")
    cleaned = re.sub(r"[^0-9,.]", "", s2)

    if cleaned == "" or cleaned.strip(",.") == "":
        return float("nan")

    has_comma = "," in cleaned
    has_period = "." in cleaned

    if has_comma and has_period:
        last_comma = cleaned.rfind(",")
        last_period = cleaned.rfind(".")
        if last_comma > last_period:
            decimal_sep, thousand_sep = ",", "."
        else:
            decimal_sep, thousand_sep = ".", ","
        num = cleaned.replace(thousand_sep, "")
        num = num.replace(decimal_sep, ".")
    elif has_comma or has_period:
        sep = "," if has_comma else "."
        last_idx = cleaned.rfind(sep)
        digits_after = len(cleaned) - last_idx - 1
        if digits_after == 2:
            num = cleaned[:last_idx].replace(sep, "") + "." + cleaned[last_idx + 1:]
        else:
            num = cleaned.replace(sep, "")
    else:
        num = cleaned

    if num == "" or num == ".":
        return float("nan")

    value = float(num)
    if negative:
        value = -abs(value)
    return value


ITEMS_RE = re.compile(r"items=(-?\d+)")
ADJ_RE = re.compile(r"adj=([+-]?\d+(?:\.\d+)?)%")
FEE_RE = re.compile(r"fee=([+-]?\d+(?:\.\d+)?)")
WAIVE_RE = re.compile(r"waive=true", re.IGNORECASE)


def parse_notes(notes):
    notes = notes or ""
    m = ITEMS_RE.search(notes)
    items = int(m.group(1)) if m else None

    m = ADJ_RE.search(notes)
    adj_pct = float(m.group(1)) / 100.0 if m else 0.0

    m = FEE_RE.search(notes)
    fee = float(m.group(1)) if m else 0.0

    waive = bool(WAIVE_RE.search(notes))

    return items, adj_pct, fee, waive


def parse_event_time(raw):
    raw = raw.strip()
    if raw == "":
        return None
    return datetime.strptime(raw, "%Y-%m-%dT%H:%M:%SZ")


def load_rows():
    import csv

    rows = []
    with open(DATA_PATH, newline="", encoding="utf-8") as f:
        reader = csv.DictReader(f)
        for idx, row in enumerate(reader):
            record_id = row["record_id"]
            event_time = parse_event_time(row["event_time"])
            region = row["region"].strip()
            channel = row["channel"].strip().lower()
            base_amount = parse_amount(row["amount_str"])
            items, adj_pct, fee, waive = parse_notes(row["notes"])

            if math.isnan(base_amount):
                net = float("nan")
            else:
                net = base_amount * (1 + adj_pct) + fee
                if waive:
                    net = 0.0

            rows.append(
                {
                    "idx": idx,
                    "record_id": record_id,
                    "event_time": event_time,
                    "region": region,
                    "channel": channel,
                    "base_amount": base_amount,
                    "items": items,
                    "net": net,
                }
            )
    return rows


def dedup_rows(rows):
    groups = {}
    for r in rows:
        groups.setdefault(r["record_id"], []).append(r)

    result = []
    for record_id, versions in groups.items():
        def sort_key(r):
            ts = r["event_time"] if r["event_time"] is not None else datetime.min
            is_real_net = 0 if not math.isnan(r["net"]) else 1
            return (-ts.timestamp(), is_real_net, r["idx"])

        best = min(versions, key=sort_key)
        result.append(best)
    return result


def median(values):
    s = sorted(values)
    n = len(s)
    mid = n // 2
    if n % 2 == 1:
        return s[mid]
    return (s[mid - 1] + s[mid]) / 2.0


def compute_answer():
    rows = load_rows()
    deduped = dedup_rows(rows)

    start = datetime(2025, 10, 1, 0, 0, 0)
    end = datetime(2025, 12, 31, 23, 59, 59)

    filtered = []
    for r in deduped:
        if r["event_time"] is None:
            continue
        if not (start <= r["event_time"] <= end):
            continue
        if r["channel"] == "phone":
            continue
        if math.isnan(r["net"]) or math.isinf(r["net"]):
            continue
        filtered.append(r)

    groups = {}
    for r in filtered:
        month = r["event_time"].strftime("%Y-%m")
        key = (r["region"], month)
        groups.setdefault(key, []).append(r)

    for key, group_rows in groups.items():
        nets = [r["net"] for r in group_rows]
        med = median(nets)
        abs_devs = [abs(n - med) for n in nets]
        mad = median(abs_devs)
        for r in group_rows:
            if mad == 0:
                r["robust_z"] = 0.0
            else:
                r["robust_z"] = 0.6745 * (r["net"] - med) / mad

    for r in filtered:
        items_eff = r["items"] if r["items"] is not None else 1
        items_eff = max(items_eff, 1)
        r["anomaly_score"] = abs(r["robust_z"]) * math.log1p(items_eff)

    # stable mergesort ordering by ascending keys applied in reverse priority,
    # then reverse the whole thing to get final descending order for the primary keys
    # Simpler: sort once with a composite key using mergesort semantics via sorted()
    # We need descending anomaly_score, descending abs(robust_z), descending event_time,
    # ascending record_id. Python's sorted() is stable (timsort/mergesort-equivalent).
    ordered = sorted(
        filtered,
        key=lambda r: (
            -r["anomaly_score"],
            -abs(r["robust_z"]),
            -r["event_time"].timestamp(),
            r["record_id"],
        ),
    )

    top10 = [r["record_id"] for r in ordered[:10]]
    return top10


def answer() -> list[str]:
    return compute_answer()


if __name__ == "__main__":
    import json

    with open("/app/answer.json", "w") as f:
        json.dump(answer(), f, default=list)

